from AlgorithmImports import *
import math


class TwoStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.pending_orders = {}

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        if spy_bar is not None and self.spy_sma.IsReady:
            spy_close = float(spy_bar.Close)
            spy_sma = float(self.spy_sma.Current.Value)

            if self.previous_spy_close is not None and self.previous_spy_sma is not None:
                spy_cross_above = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_close > spy_sma
                )
                spy_cross_below = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and spy_close < spy_sma
                )
            else:
                spy_cross_above = False
                spy_cross_below = False

            self.previous_spy_close = spy_close
            self.previous_spy_sma = spy_sma
        else:
            spy_cross_above = False
            spy_cross_below = False

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        if self.IsWarmingUp:
            return

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        if self.strategy_a_shares > 0 and not self.pending_for("A"):
            if spy_cross_below:
                self.submit_order(
                    self.spy,
                    -self.strategy_a_shares,
                    "A_SELL"
                )

        if self.strategy_b_shares > 0 and not self.pending_for("B"):
            if float(self.aapl_rsi.Current.Value) > 60:
                self.submit_order(
                    self.aapl,
                    -self.strategy_b_shares,
                    "B_SELL"
                )

        if self.strategy_a_shares == 0 and not self.pending_for("A"):
            if spy_cross_above:
                close = float(data.Bars[self.spy].Close)
                quantity = int(
                    math.floor(
                        self.Portfolio.TotalPortfolioValue * 0.40 / close
                    )
                )

                if quantity > 0:
                    self.submit_order(self.spy, quantity, "A_BUY")

        if self.strategy_b_shares == 0 and not self.pending_for("B"):
            if self.aapl_red_streak >= 3:
                close = float(data.Bars[self.aapl].Close)

                if self.Portfolio.Cash >= 20000:
                    quantity = int(math.floor(20000 / close))

                    if quantity > 0:
                        self.submit_order(self.aapl, quantity, "B_BUY")

    def submit_order(self, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, tag=tag)
        self.pending_orders[ticket.OrderId] = tag

    def pending_for(self, strategy):
        return any(
            tag.startswith(strategy + "_")
            for tag in self.pending_orders.values()
        )

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if order_id not in self.pending_orders:
            return

        tag = self.pending_orders[order_id]
        fill_quantity = int(order_event.FillQuantity)

        if tag.startswith("A_"):
            self.strategy_a_shares = max(
                0,
                self.strategy_a_shares + fill_quantity
            )
        elif tag.startswith("B_"):
            self.strategy_b_shares = max(
                0,
                self.strategy_b_shares + fill_quantity
            )

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            del self.pending_orders[order_id]
