            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and spy_close < current_spy_sma
        )

        # Evaluate sells before buys.
        if (
            self.strategy_a_lot > 0
            and not self._is_pending("A")
            and spy_crossed_below
        ):
            self._submit_sell("A", self.spy, self.strategy_a_lot)

        if (
            self.strategy_b_lot > 0
            and not self._is_pending("B")
            and current_aapl_rsi > 60
        ):
            self._submit_sell("B", self.aapl, self.strategy_b_lot)

        if (
            self.strategy_a_lot == 0
            and not self._is_pending("A")
            and spy_crossed_above
        ):
            quantity = int((0.40 * float(self.Portfolio.TotalPortfolioValue)) / spy_close)
            if quantity > 0:
                self._submit_buy("A", self.spy, quantity)

        if (
            self.strategy_b_lot == 0
            and not self._is_pending("B")
            and self.Portfolio.Cash >= 20000
        ):
            quantity = int(20000 / aapl_close)
            if quantity > 0:
                self._submit_buy("B", self.aapl, quantity)

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if order_id not in self.pending_orders:
            return

        strategy, side = self.pending_orders[order_id]

        if order_event.Status == OrderStatus.Filled:
            quantity = abs(int(order_event.FillQuantity))

            if strategy == "A":
                if side == "buy":
                    self.strategy_a_lot += quantity
                else:
                    self.strategy_a_lot = max(0, self.strategy_a_lot - quantity)
            else:
                if side == "buy":
                    self.strategy_b_lot += quantity
                else:
                    self.strategy_b_lot = max(0, self.strategy_b_lot - quantity)

            del self.pending_orders[order_id]

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            del self.pending_orders[order_id]

    def _is_pending(self, strategy):
        return any(
            pending_strategy == strategy
            for pending_strategy, _ in self.pending_orders.values()
        )

    def _submit_buy(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity)
        self.pending_orders[ticket.OrderId] = (strategy, "buy")

    def _submit_sell(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, -quantity)
        self.pending_orders[ticket.OrderId] = (strategy, "sell")
