from AlgorithmImports import *
from collections import deque
import math


class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)
        self.SetWarmUp(101, Resolution.Daily)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.closes = {
            symbol: deque(maxlen=101)
            for symbol in self.symbols.values()
        }

        self.state = {
            symbol: {
                "previous_close": None,
                "current_close": None,
                "previous_sma": None,
                "current_sma": None,
            }
            for symbol in self.symbols.values()
        }

        self.rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        available = {}

        for symbol in self.symbols.values():
            if symbol in data.Bars:
                available[symbol] = data.Bars[symbol]

        for symbol, bar in available.items():
            history = self.closes[symbol]
            current_state = self.state[symbol]

            current_state["previous_close"] = current_state["current_close"]
            current_state["previous_sma"] = current_state["current_sma"]
            current_state["current_close"] = float(bar.Close)

            if len(history) >= 100:
                current_state["current_sma"] = sum(list(history)[-100:]) / 100.0

            history.append(float(bar.Close))

            if len(history) >= 100:
                current_state["current_sma"] = sum(list(history)[-100:]) / 100.0

        if self.aapl in available:
            aapl_close = float(available[self.aapl].Close)
            previous_close = self.state[self.aapl]["previous_close"]

            if previous_close is not None:
                if aapl_close < previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

